const CACHE='meal-preap-mm-v7';
const SHELL=['./','index.html','style.css','app.mjs','runtime-config.mjs','price-client.mjs','recipe-images.mjs','engine.mjs','data.mjs','creator-recipes.mjs','recipes/catalogue.mjs','recipes/youtube.mjs','recipes/gil-jucy.mjs','recipes/social.mjs','recipes/hyzer-kelvio.mjs','recipes/creators.mjs','assets/creators/pitada.jpg','assets/creators/clara.png','assets/creators/terapia.jpg','assets/creators/jamon.jpg','assets/creators/receituando.jpg','assets/creators/gil.jpg','assets/creators/jucy.jpg','assets/creators/foodies.jpg','assets/creators/hyzer.jpg','assets/creators/kelvio.jpg','assets/dm-sans.ttf','assets/icon.svg','manifest.webmanifest'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||(url.pathname.includes('/api/')||url.pathname.endsWith('/prices-snapshot.json')))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&response.type==='basic'){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(response=>response||new Response('Sem ligação. Volta a ligar a internet para consultar os preços.',{status:503,headers:{'Content-Type':'text/plain;charset=utf-8'}}))));});
